class TaskBinding {static Object car(int id,String make,String model,int year,double price){return new Car(id,make,model,year,"Синий",price,"A"+id);}static Object[] array(Object...values){return java.util.Arrays.copyOf(values,values.length,Car[].class);}static Car[] cars(Object[]a){return (Car[])a;}static Object[] make(Object[]a,String s){return Car.make(cars(a),s);}static Object[] older(Object[]a,String s,int now,int n){return Car.older(cars(a),s,now,n);}static Object[] dearer(Object[]a,int y,double p){return Car.dearer(cars(a),y,p);}static String state(Object a){Car c=(Car)a;return c.id()+"|"+c.make()+"|"+c.model()+"|"+c.year()+"|"+c.color()+"|"+c.price()+"|"+c.registration();}static java.util.List<?> value(Object x){Car item=(Car)x;return java.util.List.of(item.id(),item.make(),item.model(),item.year(),item.color(),item.price(),item.registration());}}
